package com.kwl360.stickermaker;
import android.content.*;import android.graphics.*;import android.net.Uri;import org.json.*;import java.io.*;import java.util.*;
public class PackStore {
 static final String AUTH="com.kwl360.stickermaker.stickercontentprovider";
 static File dir(Context c,String id){File d=new File(c.getFilesDir(),"packs/"+id);d.mkdirs();return d;}
 static JSONArray packs(Context c){try{return new JSONArray(c.getSharedPreferences("packs",0).getString("data","[]"));}catch(Exception e){return new JSONArray();}}
 static void save(Context c,JSONArray a){c.getSharedPreferences("packs",0).edit().putString("data",a.toString()).apply();}
 static JSONObject get(Context c,String id){JSONArray a=packs(c);for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&id.equals(p.optString("id")))return p;}return null;}
 static String create(Context c,String name,boolean animated)throws Exception{String id="p"+java.util.UUID.randomUUID().toString().replace("-","");JSONObject p=new JSONObject();p.put("id",id);p.put("name",name);p.put("animated",animated);p.put("files",new JSONArray());p.put("version",System.currentTimeMillis());JSONArray a=packs(c);a.put(p);save(c,a);return id;}
 static int count(Context c,String id){JSONObject p=get(c,id);return p==null?0:p.optJSONArray("files").length();}
 static void add(Context c,String id,Uri uri)throws Exception{JSONObject p=get(c,id);if(p==null)throw new Exception("الحزمة غير موجودة");JSONArray f=p.getJSONArray("files");if(f.length()>=30)throw new Exception("الحد الأقصى 30 ملصقًا في الحزمة");boolean animated=p.optBoolean("animated",false);
 if(animated){ByteArrayOutputStream buffer=new ByteArrayOutputStream();try(InputStream in=openInput(c,uri)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){buffer.write(b,0,n);if(buffer.size()>500*1024)throw new Exception("الملصق المتحرك أكبر من 500 كيلوبايت");}}
 byte[] raw=buffer.toByteArray();if(raw.length<24||raw[0]!='R'||raw[1]!='I'||raw[2]!='F'||raw[3]!='F'||raw[8]!='W'||raw[9]!='E'||raw[10]!='B'||raw[11]!='P'||!hasAnim(raw))throw new Exception("الحزمة المتحركة تقبل WebP متحركًا فقط، وليس GIF");
 BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,options);if(options.outWidth!=512||options.outHeight!=512)throw new Exception("الملصق المتحرك يجب أن يكون 512×512");
 String filename="sticker_"+java.util.UUID.randomUUID().toString().replace("-","")+".webp";try(FileOutputStream out=new FileOutputStream(new File(dir(c,id),filename))){out.write(raw);}f.put(filename);if(f.length()==1){Bitmap frame=BitmapFactory.decodeByteArray(raw,0,raw.length);if(frame==null)throw new Exception("تعذر قراءة صورة الغلاف للملصق المتحرك");saveTray(c,id,frame);frame.recycle();}update(c,p);return;}
 Bitmap src;try(InputStream in=openInput(c,uri)){src=BitmapFactory.decodeStream(in);}if(src==null)throw new Exception("تعذر قراءة الصورة؛ استخدم PNG أو JPG أو WebP ثابت");Bitmap out=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(out);Paint paint=new Paint(3);float scale=Math.min(512f/src.getWidth(),512f/src.getHeight());float w=src.getWidth()*scale,h=src.getHeight()*scale;canvas.drawBitmap(src,null,new RectF((512-w)/2,(512-h)/2,(512+w)/2,(512+h)/2),paint);src.recycle();String filename="sticker_"+java.util.UUID.randomUUID().toString().replace("-","")+".webp";File file=new File(dir(c,id),filename);int q=90;do{try(FileOutputStream fos=new FileOutputStream(file)){out.compress(Bitmap.CompressFormat.WEBP,q,fos);}q-=10;}while(file.length()>100*1024&&q>=20);out.recycle();if(file.length()>100*1024){file.delete();throw new Exception("الصورة تتجاوز حجم واتساب المسموح");}f.put(filename);if(f.length()==1){Bitmap tray=BitmapFactory.decodeFile(file.getAbsolutePath());saveTray(c,id,tray);tray.recycle();}update(c,p);}
 static InputStream openInput(Context c,Uri uri)throws IOException{return "file".equals(uri.getScheme())?new FileInputStream(new File(uri.getPath())):c.getContentResolver().openInputStream(uri);}
 static String createSelection(Context c,String sourceId,boolean[] chosen)throws Exception{
 JSONObject source=get(c,sourceId);if(source==null)throw new Exception("الحزمة غير موجودة");
 JSONArray originals=source.getJSONArray("files");int n=0;for(int i=0;i<chosen.length&&i<originals.length();i++)if(chosen[i])n++;
 if(n<3||n>30)throw new Exception("اختر من 3 إلى 30 ملصقًا");
 String newId=create(c,"مختارات - "+source.optString("name"),source.optBoolean("animated"));
 JSONObject dest=get(c,newId);JSONArray selected=new JSONArray();
 try{for(int i=0;i<chosen.length&&i<originals.length();i++){if(!chosen[i])continue;String old=originals.getString(i);String name="sticker_"+UUID.randomUUID().toString().replace("-","")+".webp";
 try(InputStream in=new FileInputStream(new File(dir(c,sourceId),old));OutputStream out=new FileOutputStream(new File(dir(c,newId),name))){byte[] buf=new byte[8192];int len;while((len=in.read(buf))!=-1)out.write(buf,0,len);}selected.put(name);}
 File tray=new File(dir(c,sourceId),"tray.png");if(tray.isFile())try(InputStream in=new FileInputStream(tray);OutputStream out=new FileOutputStream(new File(dir(c,newId),"tray.png"))){byte[] buf=new byte[4096];int len;while((len=in.read(buf))!=-1)out.write(buf,0,len);}
 dest.put("files",selected);update(c,dest);return newId;
 }catch(Exception e){delete(c,newId);throw e;}
 }
 static boolean hasAnim(byte[] raw){for(int i=12;i<raw.length-3;i++){if(raw[i]=='A'&&raw[i+1]=='N'&&raw[i+2]=='I'&&raw[i+3]=='M')return true;}return false;}
 static void saveTray(Context c,String id,Bitmap src)throws Exception{Bitmap mini=Bitmap.createScaledBitmap(src,96,96,true);try(FileOutputStream os=new FileOutputStream(new File(dir(c,id),"tray.png"))){mini.compress(Bitmap.CompressFormat.PNG,100,os);}mini.recycle();}
 static void update(Context c,JSONObject p){try{p.put("version",System.currentTimeMillis());}catch(Exception ignored){}JSONArray a=packs(c);for(int i=0;i<a.length();i++){if(p.optString("id").equals(a.optJSONObject(i).optString("id")))a.put(i,p);}save(c,a);}
 static void rename(Context c,String id,String name)throws Exception{JSONObject p=get(c,id);if(p==null)throw new Exception("الحزمة غير موجودة");p.put("name",name);update(c,p);}
 static void removeSticker(Context c,String id,int index)throws Exception{JSONObject p=get(c,id);if(p==null)throw new Exception("الحزمة غير موجودة");JSONArray files=p.getJSONArray("files");if(index<0||index>=files.length())throw new Exception("ملصق غير موجود");String old=files.getString(index);JSONArray remaining=new JSONArray();for(int i=0;i<files.length();i++)if(i!=index)remaining.put(files.getString(i));new File(dir(c,id),old).delete();p.put("files",remaining);if(remaining.length()>0){String first=remaining.getString(0);Bitmap frame=BitmapFactory.decodeFile(new File(dir(c,id),first).getAbsolutePath());if(frame!=null){saveTray(c,id,frame);frame.recycle();}}else new File(dir(c,id),"tray.png").delete();update(c,p);}
 static void delete(Context c,String id){JSONArray a=packs(c),b=new JSONArray();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&!id.equals(p.optString("id")))b.put(p);}save(c,b);File d=dir(c,id);File[] fs=d.listFiles();if(fs!=null)for(File f:fs)f.delete();d.delete();}
}